#pragma once

#include <cstddef>
#include <initializer_list>
#include <iosfwd>
#include <vector>

// Matriz densa de doubles con almacenamiento contiguo en orden de filas.
class Matrix {
public:
    Matrix() = default;

    // Crea filas x columnas celdas inicializadas en `valor`.
    Matrix(std::size_t filas, std::size_t columnas, double valor = 0.0);

    // Crea desde una lista de filas: {{1, 2}, {3, 4}}.
    Matrix(std::initializer_list<std::initializer_list<double>> filas);

    static Matrix identidad(std::size_t n);

    std::size_t filas() const noexcept { return filas_; }
    std::size_t columnas() const noexcept { return columnas_; }
    std::size_t tamano() const noexcept { return datos_.size(); }
    bool vacia() const noexcept { return datos_.empty(); }

    // Acceso al buffer contiguo, sin comprobaciones.
    double* data() noexcept { return datos_.data(); }
    const double* data() const noexcept { return datos_.data(); }

    // Acceso con comprobacion de rango.
    double& operator()(std::size_t i, std::size_t j);
    double operator()(std::size_t i, std::size_t j) const;

    Matrix& operator+=(const Matrix& otra);
    Matrix& operator-=(const Matrix& otra);
    Matrix& operator*=(double escalar);

    bool casi_igual(const Matrix& otra, double tolerancia = 1e-9) const noexcept;

    friend Matrix operator+(Matrix a, const Matrix& b);
    friend Matrix operator-(Matrix a, const Matrix& b);
    friend Matrix operator*(Matrix a, double escalar);
    friend Matrix operator*(double escalar, Matrix a);
    friend Matrix operator*(const Matrix& a, const Matrix& b);
    friend std::ostream& operator<<(std::ostream& os, const Matrix& m);

private:
    std::size_t indice(std::size_t i, std::size_t j) const noexcept {
        return i * columnas_ + j;
    }
    void comprobar_indice(std::size_t i, std::size_t j) const;
    void comprobar_forma(const Matrix& otra, const char* operacion) const;

    std::size_t filas_ = 0;
    std::size_t columnas_ = 0;
    std::vector<double> datos_;
};

