namespace {

std::size_t celdas_validas(std::size_t filas, std::size_t columnas) {
    if (filas == 0 || columnas == 0) {
        throw std::invalid_argument("Matrix: las dimensiones deben ser mayores que cero");
    }
    return filas * columnas;
}

}  // namespace

Matrix::Matrix(std::size_t filas, std::size_t columnas, double valor)
    : filas_(filas),
      columnas_(columnas),
      datos_(celdas_validas(filas, columnas), valor) {}

Matrix::Matrix(std::initializer_list<std::initializer_list<double>> filas)
    : filas_(filas.size()), columnas_(filas.size() ? filas.begin()->size() : 0) {
    if (filas_ == 0 || columnas_ == 0) {
        throw std::invalid_argument("Matrix: la lista de filas no puede estar vacia");
    }
    datos_.reserve(filas_ * columnas_);
    for (const auto& fila : filas) {
        if (fila.size() != columnas_) {
            throw std::invalid_argument("Matrix: todas las filas deben tener la misma longitud");
        }
        datos_.insert(datos_.end(), fila.begin(), fila.end());
    }
}

Matrix Matrix::identidad(std::size_t n) {
    Matrix resultado(n, n, 0.0);
    for (std::size_t i = 0; i < n; ++i) resultado(i, i) = 1.0;
    return resultado;
}

void Matrix::comprobar_indice(std::size_t i, std::size_t j) const {
    if (i >= filas_ || j >= columnas_) {
        throw std::out_of_range("Matrix: indice (" + std::to_string(i) + ", " +
                                std::to_string(j) + ") fuera de rango");
    }
}

double& Matrix::operator()(std::size_t i, std::size_t j) {
    comprobar_indice(i, j);
    return datos_[indice(i, j)];
}

double Matrix::operator()(std::size_t i, std::size_t j) const {
    comprobar_indice(i, j);
    return datos_[indice(i, j)];
}

void Matrix::comprobar_forma(const Matrix& otra, const char* operacion) const {
    if (filas_ != otra.filas_ || columnas_ != otra.columnas_) {
        throw std::invalid_argument(std::string("Matrix: dimensiones incompatibles en ") + operacion);
    }
}

Matrix& Matrix::operator+=(const Matrix& otra) {
    comprobar_forma(otra, "A + B");
    for (std::size_t k = 0; k < datos_.size(); ++k) datos_[k] += otra.datos_[k];
    return *this;
}

Matrix& Matrix::operator-=(const Matrix& otra) {
    comprobar_forma(otra, "A - B");
    for (std::size_t k = 0; k < datos_.size(); ++k) datos_[k] -= otra.datos_[k];
    return *this;
}

Matrix& Matrix::operator*=(double escalar) {
    for (double& valor : datos_) valor *= escalar;
    return *this;
}

Matrix operator+(Matrix a, const Matrix& b) {
    a += b;
    return a;
}

Matrix operator-(Matrix a, const Matrix& b) {
    a -= b;
    return a;
}

Matrix operator*(Matrix a, double escalar) {
    a *= escalar;
    return a;
}

Matrix operator*(double escalar, Matrix a) {
    a *= escalar;
    return a;
}

Matrix operator*(const Matrix& a, const Matrix& b) {
    if (a.columnas_ != b.filas_) {
        throw std::invalid_argument("Matrix: A*B requiere columnas(A) == filas(B)");
    }
    Matrix resultado(a.filas_, b.columnas_, 0.0);
    const std::size_t comun = a.columnas_;
    const std::size_t columnas_b = b.columnas_;
    double* out = resultado.data();
    const double* pa = a.data();
    const double* pb = b.data();

    for (std::size_t i = 0; i < a.filas_; ++i) {
        double* fila_resultado = out + i * columnas_b;
        for (std::size_t k = 0; k < comun; ++k) {
            const double aik = pa[i * comun + k];
            const double* fila_b = pb + k * columnas_b;
            for (std::size_t j = 0; j < columnas_b; ++j) {
                fila_resultado[j] += aik * fila_b[j];
            }
        }
    }
    return resultado;
}

bool Matrix::casi_igual(const Matrix& otra, double tolerancia) const noexcept {
    if (filas_ != otra.filas_ || columnas_ != otra.columnas_) return false;
    for (std::size_t k = 0; k < datos_.size(); ++k) {
        if (std::abs(datos_[k] - otra.datos_[k]) > tolerancia) return false;
    }
    return true;
}

std::ostream& operator<<(std::ostream& os, const Matrix& m) {
    for (std::size_t i = 0; i < m.filas_; ++i) {
        for (std::size_t j = 0; j < m.columnas_; ++j) {
            if (j != 0) os << ' ';
            os << m(i, j);
        }
        os << '\n';
    }
    return os;
}

