namespace {

int fallos = 0;

void comprobar(bool condicion, const std::string& nombre) {
    if (condicion) {
        std::cout << "ok    " << nombre << '\n';
    } else {
        std::cout << "FALLO " << nombre << '\n';
        ++fallos;
    }
}

template <typename Accion>
void comprobar_lanza(Accion accion, const std::string& nombre) {
    try {
        accion();
        std::cout << "FALLO " << nombre << " (no lanzo excepcion)\n";
        ++fallos;
    } catch (const std::exception&) {
        std::cout << "ok    " << nombre << '\n';
    }
}

}  // namespace

int main() {
    const Matrix a{{1.0, 2.0}, {3.0, 4.0}};

    comprobar(a.filas() == 2 && a.columnas() == 2, "dimensiones 2x2");
    comprobar((a * Matrix::identidad(2)).casi_igual(a), "A * I == A");
    comprobar((a + a).casi_igual(Matrix{{2.0, 4.0}, {6.0, 8.0}}), "A + A");
    comprobar((a * a).casi_igual(Matrix{{7.0, 10.0}, {15.0, 22.0}}), "A * A");
    comprobar((2.0 * a).casi_igual(Matrix{{2.0, 4.0}, {6.0, 8.0}}), "2 * A");

    comprobar_lanza([&a] { [[maybe_unused]] const Matrix r = a * Matrix(3, 1); },
                    "A*B con dimensiones incompatibles");
    comprobar_lanza([&a] { [[maybe_unused]] const double v = a(2, 0); },
                    "indice fuera de rango");
    comprobar_lanza([] { [[maybe_unused]] const Matrix m(0, 3); },
                    "dimensiones cero");

    std::cout << (fallos == 0 ? "todas las pruebas pasaron\n" : "hubo fallos\n");
    return fallos == 0 ? 0 : 1;
}

#include <chrono>
#include <cstddef>
#include <iostream>
#include <random>

#include "matrix.hpp"

namespace {

Matrix aleatoria(std::size_t n, std::mt19937& rng) {
    std::uniform_real_distribution<double> dist(-1.0, 1.0);
    Matrix m(n, n);
    for (std::size_t k = 0; k < m.tamano(); ++k) m.data()[k] = dist(rng);
    return m;
}

}  // namespace

int main() {
    const std::size_t n = 512;
    std::mt19937 rng(42);
    const Matrix a = aleatoria(n, rng);
    const Matrix b = aleatoria(n, rng);

    const auto inicio = std::chrono::steady_clock::now();
    const Matrix c = a * b;
    const auto fin = std::chrono::steady_clock::now();

    const double ms = std::chrono::duration<double, std::milli>(fin - inicio).count();
    const double flops = 2.0 * static_cast<double>(n) * n * n;
    std::cout << "n = " << n << '\n';
    std::cout << "tiempo = " << ms << " ms\n";
    std::cout << "GFLOP/s = " << flops / (ms * 1e6) << '\n';
    std::cout << "c(0, 0) = " << c(0, 0) << '\n';
    return 0;
}

