#include <cstddef>
#include <iostream>

#include "matrix.hpp"

Matrix traspuesta(const Matrix& m) {
    Matrix t(m.columnas(), m.filas());
    for (std::size_t i = 0; i < m.filas(); ++i) {
        for (std::size_t j = 0; j < m.columnas(); ++j) {
            t(j, i) = m(i, j);
        }
    }
    return t;
}

int main() {
    const Matrix a{{1, 2, 3}, {4, 5, 6}};
    const Matrix b{{7, 8}, {9, 10}, {11, 12}};
    const Matrix p = a * b;

    std::cout << traspuesta(a);
    std::cout << "(A*B)^T == B^T * A^T: "
              << (traspuesta(p).casi_igual(traspuesta(b) * traspuesta(a)) ? "si" : "no") << '\n';
    std::cout << "traspuesta dos veces: "
              << (traspuesta(traspuesta(a)).casi_igual(a) ? "si" : "no") << '\n';
}

#include <cstddef>
#include <iostream>
#include <stdexcept>
#include <vector>

#include "matrix.hpp"

std::vector<double> producto_matriz_vector(const Matrix& m, const std::vector<double>& v) {
    if (m.columnas() != v.size()) {
        throw std::invalid_argument("producto_matriz_vector: dimensiones incompatibles");
    }
    std::vector<double> resultado(m.filas(), 0.0);
    for (std::size_t i = 0; i < m.filas(); ++i) {
        for (std::size_t j = 0; j < m.columnas(); ++j) {
            resultado[i] += m(i, j) * v[j];
        }
    }
    return resultado;
}

int main() {
    const Matrix a{{1, 2, 3}, {4, 5, 6}};
    const std::vector<double> v{1.0, 0.0, -1.0};
    const std::vector<double> r = producto_matriz_vector(a, v);
    std::cout << r[0] << ' ' << r[1] << '\n';   // -2 -2
}

